const CLIENT = "const $ = s => document.querySelector(s);\nconst toast = $('#toast');\nlet user = null, data = null;\nfunction message(text) { toast.textContent=text; toast.classList.add('show'); setTimeout(()=>toast.classList.remove('show'),4000); }\nasync function api(path, body) {\n  const response = await fetch(path,body ? {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)} : {});\n  const result = await response.json();\n  if (!response.ok || result.ok === false) throw Error(result.error || 'เชื่อมต่อไม่สำเร็จ');\n  return result;\n}\nfunction showMode(mode) {\n  if(mode==='admin'&&!user?.admin)return;\n  document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));\n  document.querySelectorAll('[data-panel]').forEach(p=>p.classList.toggle('active',p.dataset.panel===mode));\n}\n$('#loginBtn').onclick=()=>location.assign('/auth/login');\n$('#jiraLogin').onclick=()=>location.assign('/auth/login');\n$('#cancel').onclick=()=>$('#modal').classList.remove('open');\ndocument.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>showMode(b.dataset.mode));\n$('[data-mode=\"admin\"]').hidden=true;\n$('#searchVoteBtn').disabled=true;\nasync function loadData() {\n  data = await api('/api/data');\n  $('.intro h1').textContent=data.config.topic || 'ยังไม่ได้กำหนดหัวข้อการโหวต';\n  $('.intro .eyebrow').textContent=data.config.status==='open'?'เปิดโหวตอยู่':'ปิดโหวตแล้ว';\n  $('.deadline strong').textContent=data.config.endAt ? new Date(data.config.endAt).toLocaleString('th-TH') : 'ยังไม่ได้กำหนด';\n  $('#adminTopicInput').value=data.config.topic || '';\n  if(data.config.endAt){const d=new Date(data.config.endAt);$('#adminEndDateInput').value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}\n  $('#candidateList').replaceChildren(...data.candidates.map(c=>{const option=document.createElement('option');option.value=c.name;return option;}));\n  $('#candidateSearch').disabled=!data.candidates.length;\n  $('#searchVoteBtn').disabled=data.config.status!=='open'||!data.candidates.length||(data.config.endAt&&Date.parse(data.config.endAt)<Date.now());\n  const awards=$('[data-panel=\"admin\"] .awards');awards.replaceChildren();\n  data.results.filter(r=>r.award).forEach(r=>{const item=document.createElement('article');item.className='award';const rank=document.createElement('span');rank.className='rank';rank.textContent='อันดับ '+r.rank;const title=document.createElement('h3');title.textContent=r.award;item.append(rank,title);awards.append(item);});\n  const results=$('#realResults'); results.replaceChildren();\n  data.results.forEach(r=>{const p=document.createElement('p');p.textContent=`${r.rank}. ${r.name} — ${r.votes} คะแนน${r.award ? ' · '+r.award : ''}`;results.append(p);});\n  if(!data.candidates.length) message('ยังไม่มีรายชื่อผู้เข้าชิงใน Google Sheet');\n}\n$('#searchVoteBtn').onclick=async()=>{\n  if(!user){$('#modal').classList.add('open');return;}\n  const matches=data.candidates.filter(c=>c.name===$('#candidateSearch').value.trim());\n  if(matches.length!==1){message('กรุณาเลือกชื่อผู้เข้าชิงจากรายการ');return;}\n  const button=$('#searchVoteBtn');button.disabled=true;\n  try{await api('/api/sheet',{action:'vote',candidateId:matches[0].id});message('บันทึกโหวตลง Google Sheet แล้ว');button.textContent='โหวตเรียบร้อยแล้ว';await loadData();button.disabled=true;}catch(e){message(e.message==='Already voted'?'คุณโหวตไปแล้ว':e.message);button.disabled=false;}\n};\n$('#adminSaveSettings').onclick=async()=>{\n  try{const date=$('#adminEndDateInput').value;await api('/api/sheet',{action:'saveConfig',topic:$('#adminTopicInput').value.trim(),endAt:date ? new Date(date).toISOString() : '',status:'open'});await loadData();message('บันทึกการตั้งค่าแล้ว');}catch(e){message(e.message);}\n};\n(async()=>{\n  localStorage.removeItem('voterId');localStorage.removeItem('jiraEmail');\n  try{const result=await api('/api/session');user=result.user;if(user){$('#loginBtn').textContent=user.name+' · ออกจากระบบ';$('#loginBtn').onclick=()=>{const form=document.createElement('form');form.method='POST';form.action='/auth/logout';document.body.append(form);form.submit();};$('.landing').hidden=true;$('[data-mode=\"admin\"]').hidden=!user.admin;$('#loginStatus').textContent='เข้าสู่ระบบแล้ว: '+user.name;}}\n  catch(e){message(e.message);}\n  try{await loadData();}catch(e){$('.intro h1').textContent='โหลดข้อมูลการโหวตไม่สำเร็จ';message(e.message);}\n})();\n";
const ORIGIN = 'https://trueid-voting.chawapon-rr.chatgpt.site';
const SHEET = 'https://script.google.com/macros/s/AKfycbxOSQQdiI2e07sRRkQ7mltkTadgF4gwVMxgwpzfGyZJ33P8MzDwWw21c4Nv8ZSgl_Yi/exec';
const ADMINS = ['chawapon.k@muze.co.th', 'kittisak.bua@truedigital.com'];
const enc = new TextEncoder();
const json = (data, status = 200) => Response.json(data, {status, headers: {'Cache-Control':'no-store'}});
const cookie = (name, value, age) => `${name}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${age}`;
const cookies = r => Object.fromEntries((r.headers.get('Cookie') || '').split(';').map(x => x.trim().split('=')));
const b64 = s => btoa(String.fromCharCode(...enc.encode(s))).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');
async function hmac(value, secret) {
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), {name:'HMAC', hash:'SHA-256'}, false, ['sign','verify']);
  const bytes = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(value)));
  return Array.from(bytes, b => b.toString(16).padStart(2,'0')).join('');
}
async function sign(data, env) { const value = b64(JSON.stringify(data)); return value + '.' + await hmac('session:'+value, env.JIRA_CLIENT_SECRET); }
async function session(req, env) {
  try {
    const [value, sig] = (cookies(req).tv_session || '').split('.');
    if (!value || !sig || sig !== await hmac('session:'+value, env.JIRA_CLIENT_SECRET)) return null;
    const data = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(value.replaceAll('-','+').replaceAll('_','/')), c => c.charCodeAt(0))));
    return data.exp > Date.now() ? data : null;
  } catch { return null; }
}
function redirect(url, values=[]) { const headers = new Headers({'Location':url, 'Cache-Control':'no-store'}); values.forEach(v => headers.append('Set-Cookie',v)); return new Response(null,{status:302,headers}); }
function authError(message) { return new Response(`<!doctype html><html lang="th"><meta charset="utf-8"><title>TrueID Voting</title><main style="font:18px system-ui;max-width:600px;margin:80px auto;padding:24px"><h1>เข้าสู่ระบบไม่สำเร็จ</h1><p>${message}</p><a href="/auth/login">ลองเข้าสู่ระบบอีกครั้ง</a></main></html>`,{status:400,headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}}); }
async function sheetRead(action) {
  const response = await fetch(SHEET+'?action='+action);
  if (!response.ok) throw Error('Google Sheet ไม่ตอบกลับ ('+response.status+')');
  return response.json();
}
export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    try {
      if (url.pathname === '/auth/login') {
        if (!env.JIRA_CLIENT_ID || !env.JIRA_CLIENT_SECRET) return authError('ยังไม่ได้ตั้งค่าการเชื่อมต่อ Jira');
        const state = crypto.randomUUID();
        const target = new URL('https://auth.atlassian.com/authorize');
        target.search = new URLSearchParams({audience:'api.atlassian.com',client_id:env.JIRA_CLIENT_ID,scope:'read:me read:jira-user',redirect_uri:ORIGIN+'/oauth/callback',state,response_type:'code',prompt:'consent'}).toString();
        return redirect(target.toString(),[cookie('tv_oauth_state',state,600)]);
      }
      if (url.pathname === '/oauth/callback') {
        if (url.searchParams.has('error')) return authError('การอนุญาตเข้าถึงบัญชี Jira ถูกยกเลิก');
        if (!url.searchParams.get('state') || url.searchParams.get('state') !== cookies(req).tv_oauth_state) return authError('คำขอเข้าสู่ระบบหมดอายุ กรุณาเริ่มเข้าสู่ระบบใหม่');
        const tokenResponse = await fetch('https://auth.atlassian.com/oauth/token',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({grant_type:'authorization_code',client_id:env.JIRA_CLIENT_ID,client_secret:env.JIRA_CLIENT_SECRET,code:url.searchParams.get('code'),redirect_uri:ORIGIN+'/oauth/callback'})});
        const token = await tokenResponse.json();
        if (!tokenResponse.ok || !token.access_token) return authError('Jira ยืนยันบัญชีไม่สำเร็จ (token '+tokenResponse.status+')');
        const profileResponse = await fetch('https://api.atlassian.com/me',{headers:{Authorization:'Bearer '+token.access_token,Accept:'application/json'}});
        const profile = await profileResponse.json();
        if (!profileResponse.ok || !profile.account_id) return authError('อ่านข้อมูลบัญชี Jira ไม่สำเร็จ ('+profileResponse.status+')');
        const email = String(profile.email || '').toLowerCase();
        const user = {id:profile.account_id,email,name:profile.name || email,admin:ADMINS.includes(email),exp:Date.now()+8*3600000};
        return redirect('/#vote',[cookie('tv_session',await sign(user,env),8*3600),cookie('tv_oauth_state','',0)]);
      }
      if (url.pathname === '/auth/logout' && req.method === 'POST') {
        if (req.headers.get('Origin') !== ORIGIN) return json({error:'Forbidden'},403);
        return redirect('/',[cookie('tv_session','',0)]);
      }
      if (url.pathname === '/api/session') return json({user:await session(req,env)});
      if (url.pathname === '/api/data') {
        const [config, result] = await Promise.all([sheetRead('config'), sheetRead('results')]);
        const rows = (result.results || []).slice(1);
        return json({config,candidates:rows.map(r=>({id:r[1],name:r[2]})),results:rows.map(r=>({rank:r[0],id:r[1],name:r[2],votes:r[3],award:r[4]}))});
      }
      if (url.pathname === '/api/sheet' && req.method === 'POST') {
        if (req.headers.get('Origin') !== ORIGIN) return json({ok:false,error:'Forbidden'},403);
        const user = await session(req,env);
        if (!user) return json({ok:false,error:'กรุณาเข้าสู่ระบบด้วย Jira ก่อน'},401);
        const body = await req.json();
        if (body.action === 'saveConfig' && !user.admin) return json({ok:false,error:'ไม่มีสิทธิ์ผู้ดูแล'},403);
        if (!['vote','saveConfig'].includes(body.action)) return json({ok:false,error:'Unknown action'},400);
        body.voterId = user.id; body.voterEmail = user.email;
        const payload = JSON.stringify(body);
        const result = await fetch(SHEET,{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify({payload,signature:await hmac(payload,env.JIRA_CLIENT_SECRET)})});
        if (!result.ok) return json({ok:false,error:'Google Sheet ไม่ตอบกลับ'},502);
        return json(await result.json());
      }
      if (url.pathname.startsWith('/api/')) return json({error:'Not found'},404);
      if (url.pathname === '/client.js') return new Response(CLIENT,{headers:{'Content-Type':'text/javascript; charset=utf-8','Cache-Control':'no-store'}});
      return new Response(HTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});
    } catch { return url.pathname.startsWith('/api/') ? json({ok:false,error:'เชื่อมต่อระบบไม่สำเร็จ กรุณาลองใหม่'},502) : authError('เชื่อมต่อ Jira ไม่สำเร็จ กรุณาลองใหม่'); }
  }
};
